package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var x int64
	fmt.Fscan(reader, &x)

	// base = (-x) mod 360 in [0,360)
	base := ((-x % 360) + 360) % 360

	bestDev := int64(1 << 62)
	bestK := int64(0)

	for k := int64(0); k < 4; k++ {
		angle := (base + 90*k) % 360
		dev := angle
		if 360-angle < dev {
			dev = 360 - angle
		}
		if dev < bestDev {
			bestDev = dev
			bestK = k
		}
	}

	fmt.Println(bestK)
}
